def __init__(self, s: str="") -> None:
    self.offset = 0
    if s and len(s) >= 2:
        if s[0] in ('−', '-'):
            mult = -1
            s = s[1:]
        else:
            if s[0] == '+':
                s = s[1:]
            mult = 1
        if ':' in s:
            # Format like +01:00
            parts = s.split(':')
            if len(parts) >= 2:
                hour = int(parts[0]) if parts[0].isdigit() else 0
                minute = int(parts[1]) if parts[1].isdigit() else 0
            else:
                hour = int(s[:2]) if s[:2].isdigit() else 0
                minute = 0
        else:
            # Format like +0100 or -02
            if len(s) >= 2:
                hour = int(s[:2]) if s[:2].isdigit() else 0
                if len(s) >= 4:
                    minute = int(s[-2:]) if s[-2:].isdigit() else 0
                else:
                    minute = 0
            else:
                hour = 0
                minute = 0
        self.offset = mult * (hour * 60 + minute)
    elif s == 'Z':
